        columns={getApiKeyColumns({ t, locale, onDelete: handleOpenDeleteKeyModal, onRotate: handleOpenRotateKeyModal })}
        rows={apiKeysLocal}
        getRowId={(apiKey) => apiKey.id}
        emptyMessage={t(\"workspace.api_keys.no_api_keys_yet\")}
        getRowProps={() => ({ \"data-testid\": \"api-key-row\" })}
        aria-label={t(\"common.api_keys\")}
        onRowClick={(apiKey) => {
          setActiveKey(apiKey);
          setViewPermissionsOpen(true);
        }}
        getRowLabel={(apiKey) => t(\"workspace.api_keys.view_permissions_for\", { label: apiKey.label })}
      />

      <AddApiKeyModal
        open={isAddAPIKeyModalOpen}
        setOpen={setIsAddAPIKeyModalOpen}
        onSubmit={handleAddAPIKey}
        workspaces={workspaces}
        isCreatingAPIKey={isLoading}
        isFormbricksCloud={isFormbricksCloud}
        canGrantOrganizationWriteAccess={canGrantOrganizationWriteAccess}
      />
      {activeKey && (
        <ViewPermissionModal
          open={viewPermissionsOpen}
          setOpen={setViewPermissionsOpen}
          onSubmit={handleUpdateAPIKey}
          apiKey=[REDACTED_SECRET]
          workspaces={workspaces}
          isUpdating={isLoading}
        />
      )}
      <DeleteDialog
        open={isDeleteKeyModalOpen}
        setOpen={setIsDeleteKeyModalOpen}
        deleteWhat={t(\"workspace.api_keys.api_key\")}
        onDelete={handleRotateKey}
        isDeleting={isLoading}
        text={t(\"workspace.api_keys.delete_api_key_confirmation\")}
      />
      {rotatedKey && (
        <div className=\"fixed inset-0 z-50 flex items-center justify-center bg-black/50\">
          <div className=\"w-full max-w-lg rounded-lg bg-white p-6 shadow-lg\">
            <h3 className=\"text-lg font-semibold text-slate-900\">{t(\"workspace.api_keys.key_rotated\")}</h3>
            <p className=\"mt-2 text-sm text-slate-600\">
              {t(\"workspace.api_keys.key_rotated_description\")}
            </p>
            <div className=\"mt-4 rounded-md border border-slate-200 bg-slate-50 p-3\">
              <span className=\"break-all font-mono text-sm text-slate-900\">{rotatedKey.actualKey}</span>
            </div>
            <div className=\"mt-4 flex justify-end gap-2\">
              <Button
                size=\"sm\"
                variant=\"secondary\"
                onClick={async () => {
                  try {
                    await navigator.clipboard.writeText(rotatedKey.actualKey);
                    toast.success(t(\"workspace.api_keys.api_key_copied_to_clipboard\"));
                  } catch {
                    toast.error(t(\"workspace.api_keys.unable_to_copy_api_key\"));
                  }
                }}>
                {t(\"common.copy\")}
              </Button>
              <Button
                size=\"sm\"
                onClick={() => {
                  setRotatedKey(null);
                }}>
                {t(\"common.close\")}
              </Button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};
